"""Political pressure generated by policy choices, ministerial factions and Commons rebellions."""
import hashlib
import streamlit as st

import cabinet_management


def _clip(value, low=0.0, high=100.0):
    return max(low, min(high, float(value)))


def _stable_roll(s, key):
    raw = f"{s.get('seed', 0)}:{s.get('term', 1)}:{s.get('year', 1)}:{s.get('block', 1)}:{key}"
    return int(hashlib.sha256(raw.encode("utf-8")).hexdigest()[:8], 16) % 100


def review_policy(s, decision, option, vote):
    """Create at most one actionable political-pressure incident after a Commons vote."""
    if s.get("political_pressure_issue"):
        return None
    ideology = str(option.get("ideology", "Centric"))
    active = []
    for department, minister in s.get("cabinet_ministers", {}).items():
        minister = str(minister or "")
        if not minister or minister.startswith(("Vacant", "New appointment")):
            continue
        profile = cabinet_management.profile_for(s, department)
        faction = profile.get("faction", "Government Mainstream")
        aligned = ideology in cabinet_management.FACTION_IDEOLOGIES.get(faction, ["Centric"])
        if aligned:
            continue
        personality = profile.get("personality", "")
        loyalty = float(s.get("ministerial_loyalty", {}).get(department, 60.0))
        traits = cabinet_management.PERSONALITIES.get(personality, {})
        pressure = 48.0 + float(traits.get("ambition", 0.0)) * 18.0
        pressure += 12.0 if personality == "Public campaigner" else 0.0
        pressure += max(0.0, 60.0 - loyalty) * 0.28
        pressure += max(0.0, float(vote.get("rebels", 0)) - 10.0) * 0.12
        active.append((pressure, department, minister, faction, personality, loyalty))
    active.sort(reverse=True)
    selected = active[0] if active else None
    rebellion = int(vote.get("rebels", 0))
    if selected and selected[0] >= 52.0 and _stable_roll(s, f"{decision.get('title')}:{selected[2]}") < 62:
        pressure, department, minister, faction, personality, loyalty = selected
        leak_chance = 28 + (25 if personality == "Public campaigner" else 0) + (18 if personality == "Ambitious operator" else 0)
        leaked = _stable_roll(s, f"leak:{decision.get('title')}:{minister}") < leak_chance
        issue = {
            "kind": "ministerial_dissent", "department": department, "minister": minister,
            "faction": faction, "personality": personality, "decision": decision.get("title", "Government policy"),
            "ideology": ideology, "pressure": round(pressure, 1), "leaked": leaked,
            "created": f"{int(s.get('term', 1))}:{int(s.get('year', 1))}:{int(s.get('block', 1))}",
            "text": (
                f"{minister} is unhappy with your {ideology.lower()} approach to "
                f"{decision.get('title', 'the latest policy')}. Their {faction} faction is pressing for a change."
            ),
        }
        loyalty_map = dict(s.get("ministerial_loyalty", {}))
        loyalty_map[department] = round(_clip(loyalty - 1.5), 1)
        s.ministerial_loyalty = loyalty_map
        if leaked:
            s.media_opinion = round(_clip(float(s.get("media_opinion", 50.0)) - 1.2), 1)
            s.approval = round(_clip(float(s.get("approval", 50.0)) - 0.4), 1)
            issue["text"] += " A briefing against the Treasury has reached the political press."
        s.political_pressure_issue = issue
        s.political_pressure_history = (list(s.get("political_pressure_history", [])) + [dict(issue)])[-20:]
        return issue
    if rebellion >= 28 and _stable_roll(s, f"rebellion:{decision.get('title')}") < 48:
        issue = {
            "kind": "backbench_rebellion", "department": "", "minister": "Government backbenchers",
            "faction": "Parliamentary party", "personality": "", "decision": decision.get("title", "Government policy"),
            "ideology": ideology, "pressure": min(100.0, float(rebellion)), "leaked": False,
            "created": f"{int(s.get('term', 1))}:{int(s.get('year', 1))}:{int(s.get('block', 1))}",
            "text": f"A group of {rebellion} MPs has rebelled over {decision.get('title', 'your latest policy')}. Whips warn that further concessions may be needed.",
        }
        s.political_pressure_issue = issue
        s.political_pressure_history = (list(s.get("political_pressure_history", [])) + [dict(issue)])[-20:]
        return issue
    return None


def resolve_issue(choice, s=None):
    """Let the Chancellor choose how to handle a live political dispute."""
    s = s if s is not None else st.session_state
    issue = s.get("political_pressure_issue")
    if not issue:
        return False
    if choice not in {"stand_firm", "negotiate", "briefing"}:
        return False
    capital = int(s.get("political_capital_points", 0))
    if choice == "negotiate" and capital < 1:
        s.message = "You need one political-capital point to negotiate a compromise."
        return False
    if choice == "negotiate":
        s.political_capital_points = capital - 1
        s.headroom = round(float(s.get("headroom", 0.0)) - 0.3, 1)
    department = issue.get("department")
    loyalty = dict(s.get("ministerial_loyalty", {}))
    if department:
        current = float(loyalty.get(department, 55.0))
        if choice == "stand_firm":
            loyalty[department] = round(_clip(current - 5.0), 1)
        elif choice == "negotiate":
            loyalty[department] = round(_clip(current + 5.0), 1)
        else:
            loyalty[department] = round(_clip(current + 1.0), 1)
        s.ministerial_loyalty = loyalty
    if choice == "stand_firm":
        s.cab_opinion = round(_clip(float(s.get("cab_opinion", 50.0)) - (1.5 if department else 0.5)), 1)
        s.pm_opinion = round(_clip(float(s.get("pm_opinion", 50.0)) + 0.4), 1)
        outcome = "You stand by the decision. The Treasury keeps control of the policy, but Cabinet relations take a hit."
    elif choice == "negotiate":
        s.cab_opinion = round(_clip(float(s.get("cab_opinion", 50.0)) + 1.5), 1)
        s.pm_opinion = round(_clip(float(s.get("pm_opinion", 50.0)) + 0.5), 1)
        s.backbench_opinion = round(_clip(float(s.get("backbench_opinion", 50.0)) + 1.0), 1)
        outcome = "You negotiate a limited compromise, spending one political-capital point and £0.3bn of headroom to restore working relations."
    else:
        s.media_opinion = round(_clip(float(s.get("media_opinion", 50.0)) - 2.0), 1)
        s.approval = round(_clip(float(s.get("approval", 50.0)) - 0.8), 1)
        s.cab_opinion = round(_clip(float(s.get("cab_opinion", 50.0)) + 0.4), 1)
        outcome = "You allow the ministerial briefing to run. The dispute cools inside Cabinet, but the press questions the Government's unity."
    issue = dict(issue)
    issue["resolution"] = choice
    issue["outcome"] = outcome
    history = list(s.get("political_pressure_history", []))
    if history and history[-1].get("created") == issue.get("created"):
        history[-1] = issue
    s.political_pressure_history = history[-20:]
    s.political_pressure_issue = None
    s.message = outcome
    s.humphrey_note = "Political management is a trade-off: standing firm protects the policy, while compromise may preserve the coalition around it."
    return True
